<template>
  <div class="store-page">
    <el-card shadow="never">
      <div slot="header" class="page-header">
        <span class="title">店铺信息列表</span>
        <!-- <el-button type="primary" size="small" @click="openCreate">新增店铺</el-button> -->
         <span class="alert">请找到自己负责项目对应的店铺，更新店长信息，有任何问题，请联系王佳旺</span>
      </div>

      <!-- 搜索栏 -->
      <el-form :inline="true" @submit.native.prevent>
        <el-form-item label="关键词">
          <el-input
            v-model="keyword"
            placeholder="店铺名称/公司/平台/品牌/编号"
            clearable
            style="width: 280px"
            @keyup.enter.native="handleSearch"
            @clear="handleSearch"
          />
        </el-form-item>
        <el-form-item>
          <el-button type="primary" size="small" @click="handleSearch">查询</el-button>
          <el-button size="small" @click="handleReset">重置</el-button>
        </el-form-item>
      </el-form>

      <!-- 表格 -->
      <el-table :data="list" border stripe v-loading="loading" style="width: 100%">
        <el-table-column type="index" label="#" width="50" />
        <el-table-column prop="storeName" label="店铺名称" min-width="160" show-overflow-tooltip />
        <el-table-column prop="storeNumber" label="店铺编号" width="100" />
        <el-table-column prop="company" label="公司主体" min-width="160" show-overflow-tooltip />
        <el-table-column prop="brand" label="品牌" width="100" />
        <el-table-column prop="platform" label="平台" width="100" />
        <el-table-column prop="project" label="项目" width="100" />
        <el-table-column prop="storeManager" label="店长" width="100" />
        <el-table-column prop="storePhone" label="手机号" width="130" />
        <el-table-column prop="storeStatus" label="状态" width="100" />
        <el-table-column prop="createdate" label="创建时间" width="170" />
        <el-table-column label="操作" width="140" fixed="right">
          <template slot-scope="scope">
            <el-button type="text" size="small" @click="openEdit(scope.row)">编辑</el-button>
            <!-- <el-button type="text" size="small" style="color:#f56c6c" @click="handleDelete(scope.row)">删除</el-button> -->
          </template>
        </el-table-column>
      </el-table>

      <!-- 分页 -->
      <el-pagination
        class="pager"
        background
        layout="total, prev, pager, next, jumper"
        :total="total"
        :page-size="size"
        :current-page.sync="page"
        @current-change="loadData"
      />
    </el-card>

    <!-- 新增 / 编辑弹窗 -->
    <el-dialog :title="dialogTitle" :visible.sync="dialogVisible" width="820px" @closed="resetForm">
      <el-form ref="formRef" :model="form" :rules="rules" label-width="120px">
        <el-row :gutter="10">
          <el-col
            v-for="f in formFields"
            :key="f.prop"
            :span="f.span || 12"
          >
            <el-form-item :label="f.label" :prop="f.prop">
              <el-date-picker
                v-if="f.type === 'date'"
                v-model="form[f.prop]"
                type="datetime"
                value-format="yyyy-MM-dd HH:mm:ss"
                placeholder="只读"
                :disabled="isReadonly(f.prop)"
                style="width: 100%"
              />
              <el-input
                v-else-if="f.type === 'textarea'"
                v-model="form[f.prop]"
                type="textarea"
                :rows="2"
                placeholder="只读"
                :disabled="isReadonly(f.prop)"
              />
              <el-input
                v-else
                v-model="form[f.prop]"
                placeholder="只读"
                :disabled="isReadonly(f.prop)"
              />
            </el-form-item>
          </el-col>
        </el-row>
      </el-form>
      <div slot="footer">
        <el-button @click="dialogVisible = false">取消</el-button>
        <el-button type="primary" :loading="submitting" @click="submitForm">保存</el-button>
      </div>
    </el-dialog>
  </div>
</template>

<script>
import { pageStore, createStore, updateStore, updateStoreManager, deleteStore } from '../api/store'

export default {
  name: 'StoreList',
  data() {
    return {
      keyword: '',
      list: [],
      total: 0,
      page: 1,
      size: 10,
      loading: false,
      dialogVisible: false,
      submitting: false,
      isEdit: false,
      // 编辑弹窗中只允许修改的字段；其余一律只读
      editableFields: ['storeManager', 'channelManager'],
      form: this.emptyForm(),
      rules: {
        storeName: [{ required: true, message: '请输入店铺名称', trigger: 'blur' }]
      },
      formFields: [
        { prop: 'storeName', label: '店铺名称' },
        { prop: 'storeNumber', label: '店铺编号' },
        { prop: 'company', label: '公司主体' },
        { prop: 'brand', label: '运营品牌' },
        { prop: 'platform', label: '平台名称' },
        { prop: 'project', label: '项目名称' },
        { prop: 'saleDepartment', label: '二级销售部门' },
        { prop: 'superSalesDepartment', label: '一级销售部门' },
        { prop: 'series', label: '运营产品系列' },
        { prop: 'storeManager', label: '店长' },
        // { prop: 'storePhone', label: '绑定手机号' },
        // { prop: 'storeEmail', label: '绑定邮箱' },
        { prop: 'channelManager', label: '渠道经理' },
        { prop: 'storeStatus', label: '店铺状态' },
        { prop: 'shopName', label: '店铺名(Shop)' },
        // { prop: 'shopStatus', label: '店铺状态(Shop)' },
        // { prop: 'thirdPayName', label: '第三方收付名称' },
        // { prop: 'thirdPayNumber', label: '第三方收付账号' },
        // { prop: 'wdtStoreNumber', label: '旺店通编号' },
        // { prop: 'originalStore', label: '拆分前店铺名' },
        // { prop: 'dataExtraction', label: '数据抽取' },
        { prop: 'businessHours', label: '开店日期', type: 'date' },
        { prop: 'remark', label: '备注', span: 24, type: 'textarea' }
      ]
    }
  },
  computed: {
    dialogTitle() {
      return this.isEdit ? '编辑店铺' : '新增店铺'
    }
  },
  created() {
    this.loadData()
  },
  methods: {
    emptyForm() {
      return {
        id: '',
        storeName: '',
        storeNumber: '',
        company: '',
        brand: '',
        platform: '',
        project: '',
        saleDepartment: '',
        superSalesDepartment: '',
        series: '',
        storeManager: '',
        storePhone: '',
        storeEmail: '',
        channelManager: '',
        storeStatus: '',
        shopName: '',
        shopStatus: '',
        thirdPayName: '',
        thirdPayNumber: '',
        wdtStoreNumber: '',
        originalStore: '',
        dataExtraction: '',
        businessHours: '',
        remark: ''
      }
    },
    loadData() {
      this.loading = true
      pageStore(this.keyword, this.page, this.size)
        .then(res => {
          this.list = res.data.list || []
          this.total = res.data.total || 0
        })
        .catch(() => {})
        .finally(() => {
          this.loading = false
        })
    },
    handleSearch() {
      this.page = 1
      this.loadData()
    },
    handleReset() {
      this.keyword = ''
      this.page = 1
      this.loadData()
    },
    openCreate() {
      this.isEdit = false
      this.form = this.emptyForm()
      this.dialogVisible = true
    },
    openEdit(row) {
      this.isEdit = true
      // 复制可编辑字段，避免直接修改表格行
      const copy = this.emptyForm()
      Object.keys(copy).forEach(k => {
        copy[k] = row[k] != null ? row[k] : ''
      })
      this.form = copy
      this.dialogVisible = true
    },
    resetForm() {
      if (this.$refs.formRef) {
        this.$refs.formRef.clearValidate()
      }
    },
    isReadonly(prop) {
      // 仅 editableFields 可编辑；其余字段在编辑弹窗中只读
      return !this.editableFields.includes(prop)
    },
    submitForm() {
      this.$refs.formRef.validate(valid => {
        if (!valid) return
        this.submitting = true
        // 编辑模式只提交店长和渠道经理，其余字段不传给后端
        const api = this.isEdit ? updateStoreManager : createStore
        const payload = this.isEdit
          ? {
              id: this.form.id,
              storeManager: this.form.storeManager,
              channelManager: this.form.channelManager
            }
          : this.form
        api(payload)
          .then(() => {
            this.$message.success('保存成功')
            this.dialogVisible = false
            this.loadData()
          })
          .catch(() => {})
          .finally(() => {
            this.submitting = false
          })
      })
    },
    handleDelete(row) {
      this.$confirm(`确认删除店铺「${row.storeName || row.id}」？`, '提示', {
        type: 'warning'
      })
        .then(() => {
          return deleteStore(row.id)
        })
        .then(() => {
          this.$message.success('删除成功')
          this.loadData()
        })
        .catch(() => {})
    }
  }
}
</script>

<style scoped>
.store-page {
  padding: 16px;
}
.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.page-header .title {
  font-size: 16px;
  font-weight: 600;
}
.pager {
  margin-top: 16px;
  text-align: right;
}
.alert {
  font-size: 20px;
}
</style>
