import request from '../utils/request'

export function pageStore(keyword, page, size) {
  return request({
    url: '/store/page',
    method: 'get',
    params: { keyword, page, size }
  })
}

export function getStore(id) {
  return request({
    url: '/store/' + id,
    method: 'get'
  })
}

export function createStore(data) {
  return request({
    url: '/store',
    method: 'post',
    data
  })
}

export function updateStore(data) {
  return request({
    url: '/store',
    method: 'put',
    data
  })
}

// 编辑弹窗专用：只更新店长和渠道经理
export function updateStoreManager(data) {
  return request({
    url: '/store/manager',
    method: 'put',
    data
  })
}

export function deleteStore(id) {
  return request({
    url: '/store/' + id,
    method: 'delete'
  })
}
